/* cppi::d944a95636b141cd709ff1f6005025c3c60c9bf6f3dbdd6a2076e53e233bde7b */
SELECT DISTINCT run_id AS run_id
        FROM ci_capital_pipeline_sentry_reference
        WHERE extract_timestamp = (
            SELECT MAX(extract_timestamp) FROM ci_capital_pipeline_sentry_reference
        )

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
